BEGIN;

-- Estudiantes Gamificación (perfil local independiente)
CREATE TABLE IF NOT EXISTS "estudiantes_gamificacion" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "usuario_id" BIGINT UNIQUE NOT NULL,
  "estudiante_id" BIGINT NOT NULL,
  "curso_periodo_id" BIGINT NOT NULL,
  "paralelo" VARCHAR(2) NOT NULL CHECK (paralelo IN ('A', 'B')),
  "nombre" VARCHAR(80) NOT NULL DEFAULT '',
  "apellido_paterno" VARCHAR(80) NOT NULL DEFAULT '',
  "avatar_url" VARCHAR(500),
  "estado" VARCHAR(20) NOT NULL DEFAULT 'activo' CHECK (estado IN ('activo', 'inactivo')),
  "fecha_creacion" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "fecha_actualizacion" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- Rachas Diarias
CREATE TABLE IF NOT EXISTS "rachas_diarias" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "usuario_id" BIGINT NOT NULL,
  "fecha" DATE NOT NULL,
  "completada" BOOLEAN NOT NULL DEFAULT false,
  "aciertos" INT NOT NULL DEFAULT 0,
  "total_preguntas" INT NOT NULL DEFAULT 0,
  "porcentaje_acierto" NUMERIC(5,2) NOT NULL DEFAULT 0,
  "racha_actual" INT NOT NULL DEFAULT 0,
  "mejor_racha" INT NOT NULL DEFAULT 0,
  "salvada_con_puntos" BOOLEAN NOT NULL DEFAULT false,
  "puntos_gastados" INT NOT NULL DEFAULT 0,
  "creada_en" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "actualizada_en" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "uq_rachas_usuario_fecha" UNIQUE ("usuario_id", "fecha")
);

-- Puntos Individuales
CREATE TABLE IF NOT EXISTS "puntos_individuales" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "usuario_id" BIGINT NOT NULL,
  "fecha" DATE NOT NULL,
  "tipo" VARCHAR(50) NOT NULL CHECK (tipo IN ('respuesta_correcta', 'leer_resumen', 'salvar_racha', 'pista_examen', 'ajuste_manual', 'canje_tienda')),
  "puntos" INT NOT NULL,
  "descripcion" VARCHAR(255) NOT NULL,
  "metadata" JSONB DEFAULT '{}'::jsonb,
  "creada_en" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- Puntos Globales (por Curso-Periodo y Paralelo)
CREATE TABLE IF NOT EXISTS "puntos_globales" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "curso_periodo_id" BIGINT NOT NULL,
  "paralelo" VARCHAR(2) NOT NULL CHECK (paralelo IN ('A', 'B')),
  "fecha" DATE NOT NULL,
  "puntos_ganados" INT NOT NULL DEFAULT 0,
  "descripcion" VARCHAR(255) NOT NULL,
  "creada_en" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- Catálogo de Insignias
CREATE TABLE IF NOT EXISTS "insignias" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "codigo" VARCHAR(50) UNIQUE NOT NULL,
  "nombre" VARCHAR(100) NOT NULL,
  "descripcion" VARCHAR(255) NOT NULL,
  "icono_url" VARCHAR(500),
  "criterio" JSONB NOT NULL DEFAULT '{}'::jsonb,
  "activa" BOOLEAN NOT NULL DEFAULT true,
  "creada_en" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- Insignias Obtenidas por Estudiantes
CREATE TABLE IF NOT EXISTS "insignias_estudiante" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "usuario_id" BIGINT NOT NULL,
  "insignia_id" BIGINT NOT NULL,
  "fecha_obtencion" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "metadata" JSONB DEFAULT '{}'::jsonb,
  CONSTRAINT "uq_insignia_estudiante" UNIQUE ("usuario_id", "insignia_id")
);

-- Catálogo de Trofeos
CREATE TABLE IF NOT EXISTS "trofeos" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "codigo" VARCHAR(50) UNIQUE NOT NULL,
  "nombre" VARCHAR(100) NOT NULL,
  "descripcion" VARCHAR(255) NOT NULL,
  "icono_url" VARCHAR(500),
  "puntos" INT NOT NULL DEFAULT 0,
  "criterio" JSONB NOT NULL DEFAULT '{}'::jsonb,
  "periodo" VARCHAR(20) NOT NULL CHECK (periodo IN ('semanal', 'trimestral', 'anual')),
  "activo" BOOLEAN NOT NULL DEFAULT true,
  "creado_en" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- Trofeos Obtenidos por Estudiantes
CREATE TABLE IF NOT EXISTS "trofeos_estudiante" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "usuario_id" BIGINT NOT NULL,
  "trofeo_id" BIGINT NOT NULL,
  "fecha_obtencion" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "puntos_otorgados" INT NOT NULL DEFAULT 0,
  "metadata" JSONB DEFAULT '{}'::jsonb
);

ALTER TABLE "trofeos_estudiante" DROP CONSTRAINT IF EXISTS "uq_trofeo_estudiante";
CREATE UNIQUE INDEX IF NOT EXISTS "uq_trofeo_estudiante_periodo"
  ON "trofeos_estudiante" ("usuario_id", "trofeo_id", (COALESCE("metadata"->>'fechaDia', 'unico')));

ALTER TABLE "insignias_estudiante" DROP CONSTRAINT IF EXISTS "uq_insignia_estudiante";
CREATE UNIQUE INDEX IF NOT EXISTS "uq_insignia_estudiante_contexto"
  ON "insignias_estudiante" ("usuario_id", "insignia_id", (COALESCE("metadata"->>'contentId', 'unico')));
CREATE UNIQUE INDEX IF NOT EXISTS "uq_bono_desafios_diarios"
  ON "puntos_individuales" ("usuario_id", "fecha", ("metadata"->>'evento'))
  WHERE "metadata"->>'evento' = 'bono_desafios_diarios';

-- Catálogo de Tienda de Recompensas
CREATE TABLE IF NOT EXISTS "tienda_recompensas" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" VARCHAR(100) NOT NULL,
  "descripcion" VARCHAR(255) NOT NULL,
  "costo_puntos_individuales" INT NOT NULL,
  "tipo" VARCHAR(50) NOT NULL CHECK (tipo IN ('pista_examen', 'salvar_racha', 'cosmetico', 'otro')),
  "icono_url" VARCHAR(500),
  "stock" INT DEFAULT NULL,
  "activa" BOOLEAN NOT NULL DEFAULT true,
  "creada_en" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- Compras Canjeadas en Tienda
CREATE TABLE IF NOT EXISTS "compras_estudiante" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "usuario_id" BIGINT NOT NULL,
  "recompensa_id" BIGINT NOT NULL,
  "puntos_gastados" INT NOT NULL,
  "fecha_compra" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "usada" BOOLEAN NOT NULL DEFAULT false,
  "fecha_uso" TIMESTAMPTZ
);

-- Registro de Actividades Gamificadas Realizadas
CREATE TABLE IF NOT EXISTS "actividades_gamificadas" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "usuario_id" BIGINT NOT NULL,
  "estudiante_id" BIGINT NOT NULL,
  "tipo" VARCHAR(50) NOT NULL CHECK (tipo IN ('seleccion_multiple', 'cuestionario', 'flashcards', 'verdadero_falso', 'conectar_frases', 'drag_drop')),
  "materia_id" BIGINT NOT NULL,
  "materia_nombre" VARCHAR(120) NOT NULL,
  "titulo" VARCHAR(200) NOT NULL,
  "preguntas" JSONB NOT NULL DEFAULT '[]'::jsonb,
  "respuestas" JSONB NOT NULL DEFAULT '[]'::jsonb,
  "aciertos" INT NOT NULL DEFAULT 0,
  "total" INT NOT NULL DEFAULT 0,
  "porcentaje_acierto" NUMERIC(5,2) NOT NULL DEFAULT 0,
  "tiempo_total_ms" INT NOT NULL DEFAULT 0,
  "puntos_ganados" INT NOT NULL DEFAULT 0,
  "puntos_calidad" INT NOT NULL DEFAULT 0,
  "puntos_tiempo" INT NOT NULL DEFAULT 0,
  "completada" BOOLEAN NOT NULL DEFAULT false,
  "fecha_inicio" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "fecha_fin" TIMESTAMPTZ,
  "creada_en" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- Llaves foráneas
ALTER TABLE "insignias_estudiante"
  DROP CONSTRAINT IF EXISTS "fk_insignias_estudiante_insignia",
  ADD CONSTRAINT "fk_insignias_estudiante_insignia" FOREIGN KEY ("insignia_id") REFERENCES "insignias" ("id") ON DELETE CASCADE;

ALTER TABLE "trofeos_estudiante"
  DROP CONSTRAINT IF EXISTS "fk_trofeos_estudiante_trofeo",
  ADD CONSTRAINT "fk_trofeos_estudiante_trofeo" FOREIGN KEY ("trofeo_id") REFERENCES "trofeos" ("id") ON DELETE CASCADE;

ALTER TABLE "compras_estudiante"
  DROP CONSTRAINT IF EXISTS "fk_compras_estudiante_recompensa",
  ADD CONSTRAINT "fk_compras_estudiante_recompensa" FOREIGN KEY ("recompensa_id") REFERENCES "tienda_recompensas" ("id") ON DELETE RESTRICT;

-- Índices de consulta rápida
CREATE INDEX IF NOT EXISTS "idx_estudiantes_gm_curso_paralelo" ON "estudiantes_gamificacion" ("curso_periodo_id", "paralelo");
CREATE INDEX IF NOT EXISTS "idx_rachas_diarias_usuario_fecha" ON "rachas_diarias" ("usuario_id", "fecha" DESC);
CREATE INDEX IF NOT EXISTS "idx_puntos_individuales_usuario" ON "puntos_individuales" ("usuario_id");
CREATE INDEX IF NOT EXISTS "idx_puntos_globales_curso_paralelo" ON "puntos_globales" ("curso_periodo_id", "paralelo");
CREATE INDEX IF NOT EXISTS "idx_actividades_usuario_fecha" ON "actividades_gamificadas" ("usuario_id", "fecha_inicio" DESC);
CREATE INDEX IF NOT EXISTS "idx_actividades_materia" ON "actividades_gamificadas" ("usuario_id", "materia_id");

-- Semillas iniciales: Insignias
INSERT INTO "insignias" ("codigo", "nombre", "descripcion", "criterio", "activa") VALUES
