  ('mejor_semana', 'Mejor de la Semana', 'Mejor posicionado del paralelo en la semana', '{"posicion": 1}'::jsonb, true),
  ('alto_rendimiento', 'Alto Rendimiento del Trimestre', 'Rendimiento sobresaliente superior al 90% en el trimestre', '{"minAcierto": 0.9}'::jsonb, true),
